#include <cmath>
#include <algorithm>
extern "C" void raster(const double* p,int n,float* a,int sz,double scale){
 for(int j=0;j<n;j++){
 double rx=p[5*j]*scale,ry=p[5*j+1]*scale,w=p[5*j+2]*scale,ex=p[5*j+3],ey=p[5*j+4];
 if(w<.05)continue;
 double d=(1.38+1.075*((p[5*j+2]*.2218598696+.3)/1.187))/.2218598696*scale;
 double nx=-ey,ny=ex,hw=w/2;
 double xx[4]={rx+hw*nx,rx-hw*nx,rx-d*ex+hw*nx,rx-d*ex-hw*nx};
 double yy[4]={ry+hw*ny,ry-hw*ny,ry-d*ey+hw*ny,ry-d*ey-hw*ny};
 int x0=std::max(0,(int)std::floor(*std::min_element(xx,xx+4))-1),x1=std::min(sz-1,(int)std::ceil(*std::max_element(xx,xx+4))+1);
 int y0=std::max(0,(int)std::floor(*std::min_element(yy,yy+4))-1),y1=std::min(sz-1,(int)std::ceil(*std::max_element(yy,yy+4))+1);
 for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){
 double qx=x-rx,qy=y-ry,s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
 double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
 float v=std::max(0.,std::min(1.,std::min(s,f/g)+.5));
 a[y*sz+x]=std::max(a[y*sz+x],v);
 }
 }
}
