import os,json,ctypes,time
import numpy as np
from scipy.interpolate import CubicSpline,PchipInterpolator
from scipy.optimize import minimize
from scipy.ndimage import distance_transform_edt,gaussian_filter
from PIL import Image
L=ctypes.CDLL('/app/output/raster.so'); L.raster.argtypes=[ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_int,ctypes.c_double]
# root positions and full mark width in pixels
initial=[
[[279,342,0],[308,349,23],[349,350,25],[440,334,24],[548,321,25],[639,311,37],[695,311,40],[733,324,8],[739,326,0]],
[[389,252,0],[416,269,48],[430,309,33],[436,350,26],[443,394,16],[444,404,0]],
[[570,213,0],[594,234,52],[593,271,38],[577,321,34],[558,370,23],[542,410,0]],
[[404,428,0],[426,454,45],[425,477,43],[391,517,35],[350,563,27],[302,610,21],[255,649,12],[235,662,0]],
[[375,550,0],[395,580,39],[395,620,33],[390,680,38],[386,733,44],[389,765,19],[390,775,0]],
[[676,452,0],[696,480,51],[672,505,40],[619,546,30],[559,589,25],[503,630,20],[451,667,13],[443,669,0]],
[[522,437,0],[543,459,44],[540,509,34],[536,578,30],[538,650,29],[550,710,37],[582,740,40],[643,754,43],[708,747,45],[758,723,47],[770,687,23],[766,618,0]]]
size=512; scale=size/1024
T=np.array(Image.open('/app/target.png').convert('L'))<100
T=Image.fromarray((T*255).astype('uint8')).resize((size,size),Image.Resampling.LANCZOS)
T=np.array(T)/255.; dist=distance_transform_edt(T<.5)/scale
weight=1.65+np.minimum(dist/5,3)*1.0

def samples(p,step=1.5):
 p=np.array(p); t=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p[:,:2],axis=0),axis=1))]; t/=t[-1]
 tt=np.linspace(0,1,max(40,int(np.sum(np.linalg.norm(np.diff(p[:,:2],axis=0),axis=1))/step)))
 xy=CubicSpline(t,p[:,:2],bc_type='natural')(tt); dv=CubicSpline(t,p[:,:2],bc_type='natural')(tt,1); dv/=np.linalg.norm(dv,axis=1)[:,None]
 w=np.maximum(0,PchipInterpolator(t,p[:,2])(tt))
 return np.ascontiguousarray(np.c_[xy,w,dv])
def render(p):
 a=np.zeros((size,size),np.float32); v=samples(p)
 L.raster(v.ctypes.data,len(v),a.ctypes.data,size,scale); return a

def report(ps,label):
 aa=np.maximum.reduce([render(p) for p in ps]); b=aa>=.5; target=T>=.5
 print(label,'iou',np.sum(b&target)/np.sum(b|target),'recall',np.sum(b&target)/target.sum(),'stray',np.sum(b&(dist>4.5))/target.sum(),flush=True)
 im=np.ones((size,size,3),np.uint8)*245; im[target]=[150,150,150]; im[b]=[10,10,10]; im[b&~target]=[220,60,50]; im[target&~b]=[60,110,210]
 Image.fromarray(im).resize((1024,1024)).save('/app/output/fit_'+label+'.png')
 return aa

if __name__=='__main__':
 import argparse
 ap=argparse.ArgumentParser();ap.add_argument('--load');ap.add_argument('--rounds',type=int,default=3);args=ap.parse_args()
 ps=[np.array(p,float) for p in (json.load(open(args.load)) if args.load else initial)]
 report(ps,'start'); st=time.time()
 for rnd in range(args.rounds):
  for i in range(7):
   fixed=np.maximum.reduce([render(p) for j,p in enumerate(ps) if j!=i]); p0=ps[i].copy(); sh=p0.shape
   bounds=[]
   for k,row in enumerate(p0):
    bounds.extend([(row[0]-14,row[0]+14),(row[1]-14,row[1]+14),(0,0) if k in [0,len(p0)-1] else (max(1,row[2]-16),min(76,row[2]+16))])
   def loss(v):
    p=v.reshape(sh); a=np.maximum(fixed,render(p)); miss=np.maximum(0,T-a); extra=np.maximum(0,a-T)
    return (miss.sum()+np.sum(extra*weight))/T.sum()
   res=minimize(loss,p0.ravel(),method='Powell',bounds=bounds,options={'maxiter':12,'xtol':.09,'ftol':.00008})
   ps[i]=res.x.reshape(sh);print('round',rnd,'stroke',i,'loss',res.fun,'nfev',res.nfev,'secs',time.time()-st,flush=True)
   json.dump([p.tolist() for p in ps],open('/app/output/paths.json','w'))
  report(ps,str(rnd))
